// 设计说明：seats 数组长度恒等于 maxPlayers，空座位用 kind:'empty' 占位，
// 这样房主/客户端可以按固定索引渲染座位，避免"座位号漂移"问题。

const ID_CHARS = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // 去掉易混淆的 0/1/I/O

export class RoomHub {
  constructor() {
    this.rooms = new Map();        // roomId -> room
    this.clientRoom = new Map();   // clientId -> roomId
    this._listeners = {};
  }

  on(evt, cb) { (this._listeners[evt] ||= []).push(cb); }
  _emit(evt, data) {
    for (const cb of this._listeners[evt] || []) {
      try { cb(data); } catch (e) { console.error('room-change listener error', e); }
    }
  }

  _newId() {
    let id;
    do {
      id = '';
      for (let i = 0; i < 4; i++) id += ID_CHARS[(Math.random() * ID_CHARS.length) | 0];
    } while (this.rooms.has(id));
    return id;
  }

  createRoom({ game, maxPlayers, hostClientId, hostName, aiCount = 0 }) {
    if (!['demo', 'snake', 'mahjong', 'ddz', 'tetris'].includes(game)) throw { code: 'bad_game' };
    if (!Number.isInteger(maxPlayers) || maxPlayers < 2 || maxPlayers > 4) throw { code: 'bad_max_players' };
    const now = Date.now();
    const seats = [{ seat: 0, name: hostName || '房主', kind: 'human', clientId: hostClientId }];
    let aiN = 0;
    for (let i = 1; i < maxPlayers; i++) {
      if (aiN < aiCount) {
        aiN++;
        seats.push({ seat: i, name: `AI-${aiN}`, kind: 'ai', clientId: null });
      } else {
        seats.push({ seat: i, name: '', kind: 'empty', clientId: null });
      }
    }
    const room = { id: this._newId(), game, maxPlayers, status: 'waiting', createdAt: now, lastSeen: now, seats };
    this.rooms.set(room.id, room);
    if (hostClientId) this.clientRoom.set(hostClientId, room.id);
    this._emit('room-change', { room });
    return room;
  }

