import test from 'node:test';
import assert from 'node:assert/strict';
import { RoomHub } from '../../server/rooms.js';

test('createRoom：座位结构（human host + AI + empty）', () => {
  const hub = new RoomHub();
  const room = hub.createRoom({ game: 'ddz', maxPlayers: 3, hostClientId: 'h1', hostName: 'Alice', aiCount: 1 });
  assert.equal(room.seats.length, 3);
  assert.deepEqual(room.seats.map((s) => s.kind), ['human', 'ai', 'empty']);
  assert.equal(room.seats[0].name, 'Alice');
  assert.equal(room.seats[1].name, 'AI-1');
  assert.equal(room.status, 'waiting');
  assert.match(room.id, /workspace/);
  assert.equal(hub.roomOf('h1').id, room.id);
});

test('joinRoom：正常加入拿到空座位', () => {
  const hub = new RoomHub();
  const room = hub.createRoom({ game: 'snake', maxPlayers: 2, hostClientId: 'h1', hostName: 'A' });
  const { seat } = hub.joinRoom(room.id, 'j1', 'Bob');
  assert.equal(seat, 1);
  assert.equal(room.seats[1].kind, 'human');
  assert.equal(hub.roomOf('j1').id, room.id);
});

test('joinRoom：拒绝分支（不存在/workspace/满员）', () => {
  const hub = new RoomHub();
  const room = hub.createRoom({ game: 'snake', maxPlayers: 2, hostClientId: 'h1', hostName: 'A' });
  assert.throws(() => hub.joinRoom('XXXX', 'j1', 'B'), /workspace/);
  hub.setStatus(room.id, 'playing');
  assert.throws(() => hub.joinRoom(room.id, 'j1', 'B'), /workspace/);
  hub.setStatus(room.id, 'waiting');
  hub.joinRoom(room.id, 'j1', 'B');
  assert.throws(() => hub.joinRoom(room.id, 'j1', 'B'), /workspace/);
  const room2 = hub.createRoom({ game: 'snake', maxPlayers: 2, hostClientId: 'h2', hostName: 'C' });
  hub.joinRoom(room2.id, 'j1x', 'D');
  // 满员房
  const full = hub.createRoom({ game: 'snake', maxPlayers: 2, hostClientId: 'h3', hostName: 'E', aiCount: 1 });
  assert.throws(() => hub.joinRoom(full.id, 'j2', 'F'), /workspace/);
});

